#include "V30Journal.h"
#include <string.h>
namespace { constexpr uint32_t kMagic=0x56334A52u; }
namespace v30 {
V30Journal::V30Journal(V30JournalStorage&s):storage_(s),capacity_(s.capacity()>kV30JournalMaxRecords?kV30JournalMaxRecords:s.capacity()),nextGeneration_(1),loaded_(false),degraded_(false){memset(records_,0,sizeof(records_));memset(valid_,0,sizeof(valid_));}
uint32_t V30Journal::checksum(const V30JournalRecord&r){V30JournalRecord c=r;c.crc32=0;const uint8_t*p=reinterpret_cast<const uint8_t*>(&c);uint32_t x=2166136261u;for(size_t i=0;i<sizeof(c);++i){x^=p[i];x*=16777619u;}return x;}
bool V30Journal::validBundle(const V30JournalBundle&b){return b.payloadLen<=kV30JournalPayloadBytes&&b.critical<=1&&b.authenticated==1&&(b.direction==JournalDirection::Inbound||b.direction==JournalDirection::Outbound);}
bool V30Journal::loadRecord(size_t i){if(i>=capacity_)return false;V30JournalRecord r{};valid_[i]=false;if(!storage_.read(i,r)){if(!storage_.isEmpty(i))degraded_=true;return false;}if(r.magic!=kMagic||r.crc32!=checksum(r)||!validBundle(r.bundle)||r.generation==0||r.generation==UINT32_MAX||r.state<JournalState::Durable||r.state>JournalState::RecipientAck||(r.bundle.direction==JournalDirection::Inbound&&r.state!=JournalState::Durable)){degraded_=true;return false;}records_[i]=r;valid_[i]=true;return true;}
V30JournalRecovery V30Journal::recover(){V30JournalRecovery o{0,0,1,false};nextGeneration_=1;loaded_=true;degraded_=false;for(size_t i=0;i<capacity_;++i){if(loadRecord(i)){++o.validRecords;if(records_[i].generation>=nextGeneration_)nextGeneration_=records_[i].generation+1;}else if(!storage_.isEmpty(i))++o.discardedRecords;}if(nextGeneration_==UINT32_MAX)degraded_=true;o.nextGeneration=nextGeneration_;o.degraded=degraded_;return o;}
bool V30Journal::sameIdentity(const V30JournalBundle&a,const V30JournalBundle&b)const{return memcmp(a.origin,b.origin,32)==0&&memcmp(a.messageId,b.messageId,16)==0;}
bool V30Journal::sameBundle(const V30JournalBundle&a,const V30JournalBundle&b)const{return validBundle(a)&&validBundle(b)&&a.critical==b.critical&&a.direction==b.direction&&a.authenticated==b.authenticated&&a.payloadLen==b.payloadLen&&memcmp(a.origin,b.origin,32)==0&&memcmp(a.messageId,b.messageId,16)==0&&memcmp(a.peer,b.peer,32)==0&&memcmp(a.payload,b.payload,a.payloadLen)==0;}
int V30Journal::find(const V30JournalBundle&b)const{int f=-1;uint32_t n=0;for(size_t i=0;i<capacity_;++i)if(valid_[i]&&sameIdentity(records_[i].bundle,b)&&(f<0||records_[i].generation>=n)){f=(int)i;n=records_[i].generation;}return f;}
int V30Journal::freeIndex()const{for(size_t i=0;i<capacity_;++i)if(!valid_[i])return(int)i;return-1;}
bool V30Journal::persist(const V30JournalBundle&b,JournalState st){if(degraded_||!validBundle(b)||nextGeneration_==UINT32_MAX)return false;int i=freeIndex();if(i<0)return false;V30JournalRecord r{};r.magic=kMagic;r.generation=nextGeneration_++;r.state=st;r.bundle=b;r.crc32=checksum(r);if(!storage_.write((size_t)i,r)||!storage_.flush()){degraded_=true;return false;}V30JournalRecord rb{};if(!storage_.read((size_t)i,rb)||rb.magic!=kMagic||rb.crc32!=checksum(rb)||rb.generation!=r.generation||rb.state!=st||memcmp(&rb.bundle,&b,sizeof(b))!=0){degraded_=true;return false;}records_[i]=rb;valid_[i]=true;return true;}
JournalAdmission V30Journal::admit(const V30JournalBundle&b){if(!loaded_)recover();if(degraded_||!validBundle(b))return JournalAdmission::Rejected;int i=find(b);if(i>=0)return sameBundle(records_[i].bundle,b)?JournalAdmission::Durable:JournalAdmission::Rejected;if(freeIndex()<0)return JournalAdmission::Rejected;return persist(b,JournalState::Durable)?JournalAdmission::Durable:JournalAdmission::Rejected;}
bool V30Journal::commit(const V30JournalBundle&b){return admit(b)!=JournalAdmission::Rejected;}
JournalAckAction V30Journal::receive(const V30JournalBundle&b){if(!loaded_)recover();if(degraded_||!validBundle(b)||b.direction!=JournalDirection::Inbound)return JournalAckAction::NoAck;int i=find(b);if(i>=0)return sameBundle(records_[i].bundle,b)?JournalAckAction::DuplicateAck:JournalAckAction::NoAck;return admit(b)==JournalAdmission::Durable?JournalAckAction::AckAfterDurable:JournalAckAction::NoAck;}
bool V30Journal::peerMatches(const uint8_t*e,const uint8_t*a)const{return memcmp(e,a,32)==0;}
bool V30Journal::sameReceipt(const V30JournalRecord&r,const V30JournalReceipt&x)const{return memcmp(r.bundle.origin,x.origin,32)==0&&memcmp(r.bundle.messageId,x.messageId,16)==0;}
JournalReceiptResult V30Journal::applyReceipt(const V30JournalReceipt&x){if(!loaded_)recover();if(degraded_||x.authenticated!=1)return JournalReceiptResult::Rejected;int best=-1;uint32_t gen=0;for(size_t i=0;i<capacity_;++i)if(valid_[i]&&records_[i].bundle.direction==JournalDirection::Outbound&&sameReceipt(records_[i],x)&&records_[i].generation>=gen){best=(int)i;gen=records_[i].generation;}if(best<0)return JournalReceiptResult::Rejected;const V30JournalRecord&r=records_[best];if(!peerMatches(r.bundle.peer,x.sender)||!peerMatches(r.bundle.origin,x.recipient))return JournalReceiptResult::Rejected;if(r.state==JournalState::RecipientAck)return JournalReceiptResult::Duplicate;return persist(r.bundle,JournalState::RecipientAck)?JournalReceiptResult::Applied:JournalReceiptResult::Rejected;}
bool V30Journal::markTxAttempt(const V30JournalBundle&b){if(!loaded_)recover();if(degraded_||!validBundle(b)||b.direction!=JournalDirection::Outbound)return false;int i=find(b);if(i<0||!sameBundle(records_[i].bundle,b)||records_[i].state==JournalState::RecipientAck)return false;return persist(records_[i].bundle,JournalState::TxAttempt);}
bool V30Journal::markTxComplete(const V30JournalBundle&b){if(!loaded_)recover();if(degraded_||!validBundle(b)||b.direction!=JournalDirection::Outbound)return false;int i=find(b);if(i<0||!sameBundle(records_[i].bundle,b)||records_[i].state==JournalState::RecipientAck)return false;return persist(records_[i].bundle,JournalState::TxComplete);}
size_t V30Journal::count()const{size_t n=0;for(size_t i=0;i<capacity_;++i)n+=valid_[i]?1:0;return n;}size_t V30Journal::capacity()const{return capacity_;}
}